python
def bitRibbonsProofStrip(readings):
    a=readings
    out=[]
    for x in a:
        count=0
        while x:
            x&=x-1
            count+=1
        out.append(count)
    return out


java
class Solution {
  public int[] bitRibbonsProofStrip(int[] readings) {
    int[] a=readings; List<Integer> out=new ArrayList<>();
    {for(int x:a){int count=0;while(x!=0){x&=x-1;count++;}out.add(count);}}
    return out.stream().mapToInt(Integer::intValue).toArray();
  }
}
